import {NoteBindingAdapter,NOTE_BINDING_CONTRACT,assertCanonicalNoteBindingOwner,isCanonicalNoteBindingOwner,isCanonicalDomainBindingInputAdapter} from './foundation/notes/note-binding.js';
import {libraryNoteBindingInput,learnNoteBindingInput,spatialNoteBindingInput,libraryDonorNoteBindingInput,LIBRARY_NOTE_BINDING_INPUT_ADAPTER} from './adapters/note-binding-domains.js';
import {NOTE_FIXTURES,FIXTURES} from './adapters/library-fixtures.js';
import {createStructuredConsumerAdapter} from './adapters/structured-documents.js';

const assert=(condition,message)=>{if(!condition)throw Error(message)};
const stable=value=>JSON.stringify(value);
const run=(id,fn)=>{try{return {id,status:'PASS',evidence:fn()}}catch(error){return {id,status:'FAIL',error:String(error?.message||error)}}};
const rejects=(fn,token)=>{try{fn()}catch(error){const message=String(error?.message||error);assert(message.includes(token),`expected ${token}, got ${message}`);return message}throw Error(`expected rejection ${token}`)};
const available=evidence=>({state:'available',evidence});

function structuredBindingFixture(){
  const owner=new NoteBindingAdapter();
  const input=libraryNoteBindingInput({noteId:'note-structured-01',documentId:'KU-D05-0021',blockId:'blk-d05-p1',sourceRange:{kind:'text',quote:'subject_id ↔ object_id',start:0,end:12},route:'PERSONAL:CEP/W06/Library',availability:available({kind:'LIVE_FIXTURE'}),sourceLabel:'API Object-Level Authorization',sourceMetadata:{domainKind:'library',surface:'library',classification:'LOCAL_FIXTURE'},revisions:{documentRevision:'rev-12',contextRevision:'ctx-3'}});
  const result=owner.bind('note-structured-01',input);return {owner,input,result};
}

export function runW6BNoteBindingAdapterProof(){
  const cases=[];
  cases.push(run('01.structured-document-block-binding',()=>{const {result}=structuredBindingFixture(),b=result.binding;assert(b.source.documentId==='KU-D05-0021'&&b.source.blockId==='blk-d05-p1','structured identity missing');assert(b.source.sourceRange.kind==='text','range missing');return b}));
  cases.push(run('02.learn-document-object-binding',()=>{const owner=new NoteBindingAdapter(),learn=createStructuredConsumerAdapter('learn'),id=learn.identity().id,input=learnNoteBindingInput({noteId:'note-learn-01',documentId:id,objectId:'activity-identity-01',blockId:'learn-p1',route:'PERSONAL:CEP/learn',availability:available({kind:'LEARN_DOCUMENT_AND_ACTIVITY'})});const b=owner.bind('note-learn-01',input).binding;assert(b.source.documentId===id&&b.source.objectId==='activity-identity-01'&&b.source.blockId==='learn-p1','learn binding incomplete');return b}));
  cases.push(run('03.non-structured-spatial-shape',()=>{const owner=new NoteBindingAdapter(),b=owner.bind('note-spatial-01',spatialNoteBindingInput({noteId:'note-spatial-01',objectId:'APP-WEB-01',route:'PERSONAL:CEP/visualize',availability:available({kind:'SPATIAL_ENTITY_PRESENT'}),sourceMetadata:{domainKind:'spatial',surfaceId:'visualize',entityType:'Application'}})).binding;assert(!('documentId'in b.source)&&!('blockId'in b.source)&&b.source.objectId==='APP-WEB-01','spatial forced structured identity');return b}));
  cases.push(run('04.reopen-binding-stability',()=>{const {owner,result}=structuredBindingFixture(),before=stable(result.binding),hidden=owner.projectForPresentation('note-structured-01',{presentationId:'sticky-note-host',windowInstanceId:'window-1',hostKind:'in-page',visibility:'hidden'}),reopened=owner.projectForPresentation('note-structured-01',{presentationId:'sticky-note-host',windowInstanceId:'window-2',hostKind:'in-page',visibility:'visible'});assert(stable(hidden.binding)===before&&stable(reopened.binding)===before,'reopen changed binding');return {before,hidden:stable(hidden.binding),reopened:stable(reopened.binding)}}));
  cases.push(run('05.separate-window-binding-stability',()=>{const {owner,result}=structuredBindingFixture(),before=stable(result.binding),popout=owner.projectForPresentation('note-structured-01',{presentationId:'note-popout',windowInstanceId:'external-window-77',hostKind:'separate-window',visibility:'visible'});assert(stable(popout.binding)===before,'separate window changed binding');assert(popout.presentation.windowInstanceId==='external-window-77','presentation not projected');return popout}));
  cases.push(run('06.presentation-id-cannot-be-source',()=>{const {owner}=structuredBindingFixture();const before=stable(owner.descriptor('note-structured-01')),message=rejects(()=>owner.projectForPresentation('note-structured-01',{presentationId:'note-popout',windowInstanceId:'KU-D03-0011',hostKind:'separate-window',documentId:'KU-D03-0011'}),'PRESENTATION_IDENTITY_CANNOT_BECOME_SOURCE_IDENTITY');assert(stable(owner.descriptor('note-structured-01'))===before,'binding changed after presentation injection');return {message,bindingUnchanged:true}}));
  cases.push(run('07.malformed-note-id-rejects',()=>{const owner=new NoteBindingAdapter(),input=libraryNoteBindingInput({noteId:17,documentId:'KU-D05-0021',route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'})});return rejects(()=>owner.bind('note-17',input),'MALFORMED_BINDING_IDENTITY_TYPE')}));
  cases.push(run('08.note-id-mismatch-rejects',()=>{const owner=new NoteBindingAdapter(),input=libraryNoteBindingInput({noteId:'note-a',documentId:'KU-D05-0021',route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'})});return rejects(()=>owner.bind('note-b',input),'NOTE_ID_MISMATCH')}));
  cases.push(run('09.malformed-document-object-block-types-reject',()=>{const tokens=[];for(const patch of [{documentId:9},{objectId:{}},{blockId:['x']}]){const owner=new NoteBindingAdapter(),input=libraryNoteBindingInput({noteId:'note-bad',documentId:'KU-D05-0021',route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'}),...patch});tokens.push(rejects(()=>owner.bind('note-bad',input),'MALFORMED_BINDING_IDENTITY_TYPE'))}return tokens}));
  cases.push(run('10.contradictory-document-source-ids-reject',()=>{const owner=new NoteBindingAdapter(),input=libraryNoteBindingInput({noteId:'note-contradict',documentId:'KU-D05-0021',kuId:'KU-D03-0011',blockId:'blk-d05-p1',route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'})});return rejects(()=>owner.bind('note-contradict',input),'CONTRADICTORY_SOURCE_IDENTITY')}));
  cases.push(run('11.contradictory-domain-surface-metadata-reject',()=>{const errors=[];for(const sourceMetadata of [{domainKind:'spatial'},{surface:'learn'},{surfaceId:'runs'}]){const owner=new NoteBindingAdapter(),input=libraryNoteBindingInput({noteId:'note-meta',documentId:'KU-D05-0021',route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'}),sourceMetadata});errors.push(rejects(()=>owner.bind('note-meta',input),'CONTRADICTORY_'))}return errors}));
  cases.push(run('12.stale-unresolved-status-no-deletion',()=>{const owner=new NoteBindingAdapter(),sourceState={id:'KU-D05-0021',alive:true,blocks:['blk-d05-p1']},noteContent={id:'note-stale',text:'preserve me'},before=stable({sourceState,noteContent});owner.bind('note-stale',libraryNoteBindingInput({noteId:'note-stale',documentId:'KU-D05-0021',blockId:'blk-d05-p1',route:'PERSONAL:CEP/library',availability:{state:'stale',reason:'source-view-unavailable',evidence:{resolver:'fixture'}}}));const b=owner.descriptor('note-stale');assert(b.availability.state==='stale','stale status false');assert(stable({sourceState,noteContent})===before,'source or note content mutated');const owner2=new NoteBindingAdapter(),u=owner2.bind('note-unresolved',libraryNoteBindingInput({noteId:'note-unresolved',route:'PERSONAL:CEP/library',availability:{state:'unresolved',reason:'source-not-resolved'}})).binding;assert(Object.keys(u.source).length===0&&u.availability.state==='unresolved','unresolved truth false');return {stale:b.availability,unresolved:u.availability,externalStateUnchanged:true}}));
  cases.push(run('13.stale-to-resolved-explicit-validation',()=>{const owner=new NoteBindingAdapter();owner.bind('note-stale',libraryNoteBindingInput({noteId:'note-stale',documentId:'KU-D05-0021',blockId:'blk-d05-p1',route:'PERSONAL:CEP/library',availability:{state:'stale',reason:'resolver-offline'}}));const rejection=rejects(()=>owner.projectAvailability('note-stale',{availability:{state:'available',evidence:{resolver:'back'}}}),'EXPLICIT_SOURCE_REVALIDATION_REQUIRED');const result=owner.projectAvailability('note-stale',{source:{documentId:'KU-D05-0021',blockId:'blk-d05-p1'},availability:{state:'available',evidence:{resolver:'back',validated:true}}});assert(result.binding.availability.state==='available','resolve failed');return {rejection,resolved:result.binding.availability}}));
  cases.push(run('14.absent-non-applicable-fields-stay-absent',()=>{const owner=new NoteBindingAdapter(),b=owner.bind('note-spatial',spatialNoteBindingInput({noteId:'note-spatial',objectId:'SVC-SIEM-01',route:'PERSONAL:CEP/visualize',availability:available({kind:'ENTITY_PRESENT'})})).binding;assert(Object.keys(b.source).join(',')==='objectId','non-applicable source fields fabricated');return b.source}));
  cases.push(run('15.optional-source-metadata-only-when-supplied',()=>{const a=new NoteBindingAdapter(),b1=a.bind('note-no-meta',libraryNoteBindingInput({noteId:'note-no-meta',documentId:'KU-D05-0021',route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'})})).binding;assert(!('sourceLabel'in b1)&&!('sourceMetadata'in b1),'optional metadata invented');const b=new NoteBindingAdapter(),b2=b.bind('note-meta',libraryNoteBindingInput({noteId:'note-meta',documentId:'KU-D05-0021',route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'}),sourceLabel:'Supplied label',sourceMetadata:{z:1,a:'two'}})).binding;assert(b2.sourceLabel==='Supplied label'&&b2.sourceMetadata.a==='two','supplied metadata lost');return {absent:Object.keys(b1),supplied:b2.sourceMetadata}}));
  cases.push(run('16.no-source-domain-mutation-bind-rebind-status',()=>{const source={document:{id:'KU-D05-0021',revision:'rev-12'},object:{id:'object-1',state:'ACTIVE'}},before=stable(source),owner=new NoteBindingAdapter();owner.bind('note-safe',libraryNoteBindingInput({noteId:'note-safe',documentId:source.document.id,objectId:source.object.id,route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'})}));owner.projectAvailability('note-safe',{availability:{state:'stale',reason:'view-closed'}});owner.rebind('note-safe',libraryNoteBindingInput({noteId:'note-safe',documentId:source.document.id,objectId:source.object.id,route:'PERSONAL:CEP/library',availability:{state:'stale',reason:'view-closed'},contextMetadata:{contextRevision:'ctx-2'}}));assert(stable(source)===before,'source mutated');return {sourceUnchanged:true}}));
  cases.push(run('17.failed-rebind-is-atomic',()=>{const {owner,result}=structuredBindingFixture(),before=stable(result.binding),input=libraryNoteBindingInput({noteId:'note-structured-01',documentId:77,blockId:'blk-new',route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'})}),message=rejects(()=>owner.rebind('note-structured-01',input),'MALFORMED_BINDING_IDENTITY_TYPE'),after=stable(owner.descriptor('note-structured-01'));assert(before===after,'failed rebind partially mutated');return {message,exactPriorRetained:true}}));
  cases.push(run('18.fake-same-name-owner-and-adapter-rejected',()=>{const fakeOwner={owner:'NoteBindingAdapter',contract:NOTE_BINDING_CONTRACT},ownerRejected=rejects(()=>assertCanonicalNoteBindingOwner(fakeOwner),'NON_CANONICAL_NOTE_BINDING_OWNER'),realOwner=new NoteBindingAdapter();assert(isCanonicalNoteBindingOwner(realOwner),'real owner not branded');const fakeAdapter={id:'LibraryNoteBindingInputAdapter',domainKind:'library',surfaceId:'library',allowedSourceFields:['documentId'],input:x=>x};assert(!isCanonicalDomainBindingInputAdapter(fakeAdapter),'fake adapter branded');const input={adapter:fakeAdapter,noteId:'note-fake',domainKind:'library',surfaceId:'library',source:{documentId:'KU-D05-0021'},route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'})},adapterRejected=rejects(()=>realOwner.bind('note-fake',input),'NON_CANONICAL_DOMAIN_BINDING_ADAPTER');assert(isCanonicalDomainBindingInputAdapter(LIBRARY_NOTE_BINDING_INPUT_ADAPTER),'real domain adapter not branded');return {ownerRejected,adapterRejected}}));
  cases.push(run('19.no-content-window-persistence-ownership',()=>{const excluded=NOTE_BINDING_CONTRACT.excludedOwnership;for(const item of ['note-content','sticky-note-window-geometry','sticky-note-window-lifecycle','persistence-storage','dom-focus','dom-scroll'])assert(excluded.includes(item),`missing excluded ownership ${item}`);const owner=new NoteBindingAdapter();assert(!('save'in owner)&&!('deleteSource'in owner)&&!('setGeometry'in owner),'forbidden semantic methods introduced');return {responsibilities:NOTE_BINDING_CONTRACT.responsibilities,excluded}}));
  cases.push(run('20.deterministic-serializable-descriptors',()=>{const make=metadata=>{const owner=new NoteBindingAdapter();return owner.bind('note-det',libraryNoteBindingInput({noteId:'note-det',documentId:'KU-D05-0021',blockId:'blk-d05-p1',route:'PERSONAL:CEP/library',availability:{state:'available',evidence:{z:3,a:1}},sourceMetadata:metadata})).binding},a=make({z:9,a:{y:2,x:1}}),b=make({a:{x:1,y:2},z:9});assert(stable(a)===stable(b),'semantic key order changed descriptor');assert(stable(JSON.parse(JSON.stringify(a)))===stable(a),'descriptor not serializable');return {serialized:stable(a)}}));
  cases.push(run('21.library-current-donor-fixtures-representable',()=>{const owner=new NoteBindingAdapter(),out=[];for(const note of NOTE_FIXTURES){const b=owner.bind(note.id,libraryDonorNoteBindingInput(note)).binding;assert(b.noteId===note.id&&b.source.documentId===note.binding.kuId&&b.source.blockId===note.binding.blockId&&b.route===note.binding.route,'donor fixture not representable');if(note.binding.selection!==null)assert(b.source.sourceRange===note.binding.selection,'selection lost');out.push(b)}assert(out.length===2,'expected two donor notes');return out.map(x=>({noteId:x.noteId,source:x.source,route:x.route}))}));
  cases.push(run('22.learn-current-note-route-representable',()=>{const learn=createStructuredConsumerAdapter('learn'),owner=new NoteBindingAdapter(),source=learn.bindNote({blockId:'learn-p1',selection:null,route:'PERSONAL:CEP/learn'}),b=owner.bind('note-learn-current',learnNoteBindingInput({noteId:'note-learn-current',documentId:source.documentId,blockId:source.blockId,route:source.route,availability:available({kind:'CURRENT_STRUCTURED_LEARN_FIXTURE'})})).binding;assert(b.source.documentId===source.documentId&&b.source.blockId===source.blockId&&b.route===source.route,'current Learn binding not representable');return {legacyShape:source,canonical:b}}));
  cases.push(run('23.unrelated-revisions-not-forced-equal',()=>{const owner=new NoteBindingAdapter(),b=owner.bind('note-revs',learnNoteBindingInput({noteId:'note-revs',documentId:'learn-document-trust-boundaries',objectId:'activity-identity-01',route:'PERSONAL:CEP/learn',availability:available({kind:'FIXTURE'}),revisions:{documentRevision:'learn-rev-1',objectRevision:'activity-rev-17',contextRevision:'route-rev-3'}})).binding;assert(new Set(Object.values(b.revisions)).size===3,'unrelated revisions collapsed');return b.revisions}));
  cases.push(run('24.block-without-document-rejected',()=>{const owner=new NoteBindingAdapter(),input=LIBRARY_NOTE_BINDING_INPUT_ADAPTER.input({noteId:'note-block-only',domainKind:'library',surfaceId:'library',source:{blockId:'blk-d05-p1'},route:'PERSONAL:CEP/library',availability:available({kind:'FIXTURE'})});return rejects(()=>owner.bind('note-block-only',input),'BLOCK_REQUIRES_DOCUMENT_IDENTITY')}));
  cases.push(run('25.spatial-rejects-structured-only-field',()=>{const owner=new NoteBindingAdapter(),input=spatialNoteBindingInput({noteId:'note-spatial-bad',objectId:'APP-WEB-01',route:'PERSONAL:CEP/visualize',availability:available({kind:'FIXTURE'})});input.source.documentId='KU-D05-0021';return rejects(()=>owner.bind('note-spatial-bad',input),'SOURCE_FIELD_NOT_APPLICABLE')}));
  cases.push(run('26.unknown-presentation-cannot-create-binding',()=>{const owner=new NoteBindingAdapter(),message=rejects(()=>owner.projectForPresentation('note-new',{presentationId:'popout-1',windowInstanceId:'window-new',hostKind:'separate-window',visibility:'visible'}),'UNKNOWN_NOTE_BINDING');assert(owner.snapshot().length===0,'presentation created binding');return {message,bindingCount:0}}));
  cases.push(run('27.library-source-fixture-identity-validated',()=>{const fixture=FIXTURES['KU-D05-0021'],owner=new NoteBindingAdapter(),b=owner.bind('note-source-fixture',libraryNoteBindingInput({noteId:'note-source-fixture',documentId:fixture.id,blockId:'blk-d05-p1',route:'PERSONAL:CEP/W02/Library',availability:available({kind:'FIXTURE_DOCUMENT_PRESENT'}),revisions:{documentRevision:fixture.revision}})).binding;assert(b.source.documentId===fixture.id&&b.revisions.documentRevision===fixture.revision,'fixture identity mismatch');return {documentId:b.source.documentId,revision:b.revisions.documentRevision}}));
  const pass=cases.filter(test=>test.status==='PASS').length,fail=cases.length-pass;
  return {schemaVersion:1,kind:'W6_B_NOTE_BINDING_ADAPTER_EXECUTABLE_PROOF',status:fail?'FAIL':'PASS',pass,fail,caseCount:cases.length,contract:NOTE_BINDING_CONTRACT,cases};
}
